import {$,parseCSV,stats,escapeHTML as esc,download} from './core.js';
const sample='Month,Visitors,Enquiries\nJanuary,1240,42\nFebruary,1680,58\nMarch,1520,49\nApril,2130,76\nMay,2460,84\nJune,2810,103';let data;
$('#app').innerHTML=`<div class="panel"><div class="toolbar"><label>Open CSV (up to 2 MB)<input id="file" type="file" accept=".csv,text/csv"></label><button id="sample" class="secondary">Load sample</button></div><p class="small">Sample data is fictional website traffic. Your CSV stays on this device.</p></div><div class="toolbar"><label>Numeric column<select id="column"></select></label><button id="export" class="secondary">Export summary ↓</button></div><div id="metrics" class="grid"></div><div class="panel" style="margin-top:20px"><h2 id="chart-title">Values by row</h2><div id="chart" class="chart" role="img"></div><p class="small" id="chart-note"></p></div><h2>Data preview</h2><div class="table-wrap panel" id="table"></div>`;
function load(text){try{const parsed=parseCSV(text);if(parsed.rows.length>20000)throw Error('Please use a CSV with at most 20,000 rows.');data=parsed;$('#column').innerHTML=data.headers.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('');const first=data.headers.findIndex((_,i)=>stats(data.rows.map(r=>r[i])));$('#column').value=String(Math.max(first,0));$('#table').innerHTML=`<table><thead><tr>${data.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.rows.slice(0,100).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('#status').textContent=`Loaded ${data.rows.length} rows. Preview shows up to 100.`;render()}catch(e){$('#status').textContent=e.message}}
function render(){const i=Number($('#column').value),s=stats(data.rows.map(r=>r[i]));$('#metrics').innerHTML=s?[['Numeric values',s.count],['Mean',s.mean],['Median',s.median]].map(([l,v])=>`<div class="panel"><span class="eyebrow">${l}</span><div class="metric">${Number(v.toFixed(2)).toLocaleString()}</div></div>`).join(''):'<p class="empty">This column has no numeric values. Select another column.</p>';const vals=data.rows.map((r,index)=>({v:r[i].trim(),index})).filter(o=>o.v!==''&&Number.isFinite(Number(o.v))).slice(0,24);let max=Math.max(...vals.map(o=>Math.abs(Number(o.v))),1);$('#chart').innerHTML=vals.map(o=>`<div class="bar" style="height:${Math.max(1,Math.abs(Number(o.v))/max*100)}%;background:${Number(o.v)<0?'#bb8774':'#91aa74'}" title="Row ${o.index+1}: ${esc(o.v)}"><span class="bar-label">${esc(o.v)}</span></div>`).join('');$('#chart').setAttribute('aria-label',`${data.headers[i]}: ${vals.map(o=>o.v).join(', ')}`);$('#chart-title').textContent=data.headers[i]+' by row';$('#chart-note').textContent='First 24 numeric values. Bar height represents absolute magnitude; negative values are terracotta. Blank and nonnumeric cells are excluded.';}
$('#column').onchange=render;$('#sample').onclick=()=>load(sample);$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){$('#status').textContent='File exceeds 2 MB.';return}try{load(await f.text())}catch{$('#status').textContent='Could not read this file.'}};$('#export').onclick=()=>download('data-lens-summary.json',JSON.stringify({rows:data.rows.length,columns:data.headers.map((name,i)=>({name,statistics:stats(data.rows.map(r=>r[i]))}))},null,2),'application/json');load(sample);
